			out.append(p);
			continue;
		}
		File f = new File(p.substring(0, p.length() - 2));
		File[] files = f.listFiles();
		if (files == null) continue;
		for (File file : files) {
			if (file.isFile()) {
				if (out.length() > 0) out.append(File.pathSeparator);
				out.append(p, 0, p.length() - 1);
				out.append(file.getName());
			}
		}
	}
	return out.toString();
}

